begin;
create table public.catalogue_reviews (
 id uuid primary key,product_slug text not null references public.products(slug),rating integer not null check(rating between 1 and 5),headline text not null check(length(headline) between 1 and 120),comment text not null check(length(comment) between 1 and 1200),author_label text not null,created_at timestamptz not null,is_sample boolean not null default true check(is_sample)
);
alter table public.catalogue_reviews enable row level security;
revoke all on public.catalogue_reviews from public,anon,authenticated;
grant select on public.catalogue_reviews to anon,authenticated;
create policy published_sample_reviews on public.catalogue_reviews for select to anon,authenticated using(is_sample and exists(select 1 from public.products p where p.slug=product_slug and p.active));
create index catalogue_reviews_product_created on public.catalogue_reviews(product_slug,created_at desc);
commit;
